import assert from 'node:assert/strict';

// Independent expected names/parents/identities and directed meanings, not
// generated by the product, its reducer, or a model completion verdict.
// This is a structure/readback audit. Painted shapes are checked separately.
const canonical = value => Array.isArray(value) ? value.map(canonical) : value !== null && typeof value === 'object'
  ? Object.fromEntries(Object.keys(value).sort().map(k => [k, canonical(value[k])])) : value;
const bag = rows => rows.map(row => JSON.stringify(canonical(row))).sort();
export async function auditReferenceDiagram({ log, ui, expected, initialRecords, protocol, stage }) {
  const graph = await protocol.verifyDecisionLog(log);
  assert.equal(ui.head, graph.head, 'UI reports this exact reduced head');
  assert.deepEqual(ui.records, graph.records, 'UI and independently reduced records are identical');
  const added = !['before', 'undo'].includes(stage);
  const wantedNodes = [...expected.initialNodes, ...(added ? expected.addedNodes : [])];
  const wantedEdges = added ? expected.addedEdges : [];
  const regions = graph.records.filter(r => r.type === 'region'), aliases = new Map();
  for (const region of regions) {
    if (expected.initialNodes.some(node => node.id === region.id)) { aliases.set(region.id, region.id); continue; }
    const description = JSON.parse(region.summary);
    assert.equal(description.schema, 'voice-ui.part-description/2');
    assert.deepEqual(Object.keys(description), ['schema', 'key', 'purpose']);
    assert.ok(expected.addedNodes.some(node => node.id === description.key), 'every new region has a known identity');
    aliases.set(region.id, description.key);
  }
  assert.equal(new Set(aliases.values()).size, aliases.size, 'no identity is reused across regions');
  const actualNodes = regions.map(region => ({id: aliases.get(region.id), label: region.label, kind: region.kind,
    parent: region.parent === null ? null : aliases.get(region.parent), summary: region.summary}));
  assert.deepEqual(bag(actualNodes), bag(wantedNodes), 'all names, kinds, parents and exact descriptions match');
  const actualEdges = graph.records.filter(r => r.type === 'relation').map(r => ({from:aliases.get(r.from),to:aliases.get(r.to),kind:r.kind,label:r.label}));
  assert.deepEqual(bag(actualEdges),bag(wantedEdges),'the two equal names are not interchangeable endpoints');
  for (const record of initialRecords) assert.ok(graph.records.some(r => JSON.stringify(r) === JSON.stringify(record)), 'pre-existing structure and pins remain unchanged');
  assert.equal(ui.view?.resourceComposition === undefined || ui.view?.resourceComposition?.resources?.length === 0,true,'no image was manufactured for identity-only parts');
  return {status:'PASS',scope:'REFERENCE_SUBSET_STRUCTURE_AND_UI_READBACK',head:graph.head,
    expectedNodes:wantedNodes.length,expectedEdges:wantedEdges.length,actualNodes,actualEdges,paintedIcons:'NOT_COVERED'};
}

// Synthetic choice policy receives requested changes, never the expectation
// file or a result from the independent audit. It selects an offered delta.
export function referenceChoice(state, changes) {
  for(const change of changes) {
    if(change.key) {
      if(state.selected.some(s=>s.key===change.key)) continue;
      return state.candidates.find(c=>c.part===change.key&&c.parent===change.parent)?.id;
    }
    const regionFor = id => state.selected.find(s=>s.key===id)?.region ?? id;
    const from=regionFor(change.from),to=regionFor(change.to);
    if(state.edges.some(e=>e.from===from&&e.to===to&&e.kind===change.kind&&e.label===change.label)) continue;
    return state.candidates.find(c=>c.from===from&&c.to===to&&c.kind===change.kind&&c.label===change.label)?.id;
  }
  return 'none';
}
